python3 << 'PYEOF'
import yaml

with open('/tmp/decisions.yaml') as f:
    data = yaml.safe_load(f)

decisions = data['decisions']

# D251 vs D268 for Attn k=0.95 seed42
for d in decisions:
    if d['id'] in ['D251', 'D265', 'D268']:
        print(f"\n{d['id']}:")
        print(f"  summary: {d['summary']}")
        print(f"  rationale: {d['rationale'][:400]}")
        for exp in d.get('related_experiments', []):
            eid = exp.get('exp_id', '')
            if 'attn' in eid and 'k095' in eid and 'long' in eid:
                print(f"  EXP: {eid} -> {exp.get('result','')}")

# D289 Attn k=0.7 seed43: mean=53.7±0.1
# This means s42=53.6 (since (53.6+53.8)/2 = 53.7)
print("\n\nD289 Attn k=0.7:")
for d in decisions:
    if d['id'] == 'D289':
        print(f"  {d['summary']}")
        for exp in d.get('related_experiments', []):
            eid = exp.get('exp_id', '')
            if 'attn' in eid and 'k07' in eid:
                print(f"  EXP: {eid} -> {exp.get('result','')}")
PYEOF

